# --- shipped, read by no suite -------------------------------------------------------------------
# Documentation: the commit hook skips a commit that stages nothing else.
exempt docs/** *.md setup/README.md
# A port's parity table: the review record of a pytest suite that replaced shell suites.
exempt tests/*.parity.md
# Tools with no suite of their own; the tree checks above still read them.
exempt private_dot_local/bin/executable_git-merge-diff private_dot_local/bin/executable_nvim-healthdump
exempt setup/chezmoi-safe-apply Brewfile
# Install scripts chezmoi runs at apply time; no suite renders them.
exempt run_*.sh run_*.sh.tmpl
# chezmoi metadata and fragments no suite reads.
exempt .chezmoidata.yaml .chezmoiexternal.toml.tmpl .chezmoiremove .chezmoitemplates/zprofile.linux
exempt .gitignore .us-spelling-lint
# The landing gate's audit register (verify-task-io reads it at landing; no suite does).
exempt .verify-task-io.toml
# Configuration and content deployed as is.
exempt dot_claude/CLAUDE.md.tmpl dot_claude/standards/** dot_claude/skills/** .claude/skills/*
exempt dot_config/** private_Library/** private_dot_local/share/**
exempt dot_editorconfig dot_ssh/** dot_tmux.conf dot_xbindkeysrc dot_xinitrc dot_Xresources.tmpl
